export const iconNames = Object.freeze(Object.keys(REGULAR));

/* One icon. Decorative by default - the control that holds it carries the
   accessible name. `filled` switches to the fill weight for an active,
   earned or live state. Size is in CSS pixels; 18, 20 and 24 are the steps. */
export function icon(name, { filled = false, size = 20, className = '' } = {}) {
  const body = (filled && FILL[name]) || REGULAR[name] || REGULAR.compass;
  const cls = className ? ` class="${className}"` : '';
  return `<svg${cls} viewBox="0 0 256 256" width="${size}" height="${size}" fill="currentColor" aria-hidden="true" focusable="false">${body}</svg>`;
}
